-- 2026-10-31l UNDO: removes donor backgrounds batch 2 (2026-10-31l-donor-profiles-batch2.sql): deletes the 13 profiles
-- (their 16 slugs go with them by the foreign key), each only where it still holds the 2026-10-31l facts (md5), and the
-- slug jcb-sales-ltd. The 25 earlier profiles and their 41 slugs are not touched.
-- Guards (RAISE): back to 25 profiles, 41 slugs, 172 facts; the 25 earlier profiles unchanged.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

CREATE TEMP TABLE prof_before ON COMMIT DROP AS SELECT key, md5(to_jsonb(p)::text) AS h FROM public.donor_profiles p WHERE key NOT IN ('alasdair-locke', 'bassim-haidar', 'christopher-barry-wood', 'christopher-john-rea', 'david-grainger', 'jeremy-elliott-san', 'kamal-pankhania', 'mark-petterson', 'mou-operations', 'nick-candy', 'renewable-energy-partnerships', 'scottish-unionist-association-trust', 'tisun-investments');
CREATE TEMP TABLE dp_file (key text PRIMARY KEY, name text NOT NULL, kind text NOT NULL, n integer NOT NULL, facts jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO dp_file (key, name, kind, n, facts) VALUES
  ('alasdair-locke', 'Alasdair Locke', 'individual', 8, $df$[{"label":"Who they are","text":"Alasdair Locke is a businessman who founded the oil drilling and engineering contractor Abbot Group and the petrol station owner Motor Fuel Group, and is Independent non executive Chairman of First Property Group.","source":{"title":"First Property Group: Alasdair Locke","url":"https://www.fprop.com/team/alasdair-locke/"}},{"label":"Business","text":"He began in investment banking at Citigroup in 1974, founded a Singapore based shipping and offshore oil services finance firm in 1982, and founded Abbot Group plc in 1990, floating it in 1995; it was sold to private equity in 2008.","source":{"title":"First Property Group: Alasdair Locke","url":"https://www.fprop.com/team/alasdair-locke/"}},{"label":"Business","text":"He founded and chaired Motor Fuel Group, which has petrol stations across the UK, and is a former chair of Abbot Group.","source":{"title":"The Edinburgh Reporter: Chair and treasurer appointed to Scottish Conservatives (16 November 2024)","url":"https://theedinburghreporter.co.uk/2024/11/chair-and-treasurer-appointed-to-scottish-conservatives"}},{"label":"Business","text":"He has chaired Well-Safe Solutions since it was formed in August 2017; the company describes its work as well life cycle services for the energy sector, from drilling through decommissioning.","source":{"title":"Well-Safe Solutions: Alasdair Locke","url":"https://www.wellsafesolutions.com/alasdair-locke/"}},{"label":"Ownership and control","text":"Companies House lists Mr Alasdair James Dougall Locke as the person with significant control of Glenrinnes Farms Limited, holding 75 per cent or more of its shares and voting rights.","source":{"title":"Companies House: GLENRINNES FARMS LIMITED (SC147083), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/SC147083/persons-with-significant-control"}},{"label":"Ownership and control","text":"Glenrinnes Farms Limited is the person with significant control of Well-Safe Solutions Limited, owning more than 50 per cent but less than 75 per cent of its shares.","source":{"title":"Companies House: WELL-SAFE SOLUTIONS LIMITED (SC556936), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/SC556936/persons-with-significant-control"}},{"label":"Ownership and control","text":"Companies House lists him as a director of First Property Group plc since July 2000, Glenrinnes Distillery Limited since 2016 and several Well-Safe companies, and as a former director of Abbot Group Limited until November 2009.","source":{"title":"Companies House: Alasdair James Dougall LOCKE, appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/D2mdc_r95BXvRnxChggSMRF5p9s/appointments"}},{"label":"Public roles","text":"He was appointed chair of the Scottish Conservatives on 16 November 2024 under the leader Russell Findlay.","source":{"title":"The Edinburgh Reporter: Chair and treasurer appointed to Scottish Conservatives (16 November 2024)","url":"https://theedinburghreporter.co.uk/2024/11/chair-and-treasurer-appointed-to-scottish-conservatives"}}]$df$::jsonb),
  ('bassim-haidar', 'Bassim Haidar', 'individual', 4, $df$[{"label":"Who they are","text":"Bassim Haidar is a technology businessman born in Nigeria to Lebanese parents who moved to the UK in 2010. In April 2025 he pledged £1 million to Reform UK, having previously given more than £700,000 to the Conservatives.","source":{"title":"Arab News: Millionaire donor of Lebanese heritage defects from Conservatives to Reform UK (27 April 2025)","url":"https://www.arabnews.com/world/millionaire-donor-of-lebanese-heritage-defects-from-conservatives-to-reform-uk-2598660"}},{"label":"Business","text":"He founded Channel IT in 2003 to supply the Nigerian telecoms industry and Channel VAS in 2011, a provider of mobile financial services for emerging markets; earlier he helped found Intercomm Ltd (1991) and GMT (1995).","source":{"title":"World Economic Forum: Bassim Haidar","url":"https://www.weforum.org/people/bassim-haidar/"}},{"label":"Business","text":"He is the founder of Optasia, a fintech company whose platform lets mobile operators and banks provide microloans, airtime advances and small business credit. It listed on the Johannesburg Stock Exchange in November 2025, valued at R23.5 billion.","source":{"title":"Mail & Guardian: African founded firm Optasia becomes most extensive fintech JSE listing (7 November 2025)","url":"https://mg.co.za/business/2025-11-07-african-founded-firm-optasia-becomes-most-extensive-fintech-jse-listing/"}},{"label":"Business","text":"Arab News reported that his business interests include a property portfolio worth over £100 million, a Caribbean hotel and a loans company.","source":{"title":"Arab News: Millionaire donor of Lebanese heritage defects from Conservatives to Reform UK (27 April 2025)","url":"https://www.arabnews.com/world/millionaire-donor-of-lebanese-heritage-defects-from-conservatives-to-reform-uk-2598660"}}]$df$::jsonb),
  ('christopher-barry-wood', 'Professor Christopher Barry Wood', 'individual', 6, $df$[{"label":"Who they are","text":"Professor Christopher Wood is a former consultant surgeon who trained at the Welsh National School of Medicine and worked at the Royal Postgraduate Medical School at Hammersmith Hospital, and is described as a serial entrepreneur in developing new medicines.","source":{"title":"Welsh Conservatives: Welsh Conservatives appoint surgeon, CEO and top headteacher for health, economy and education (3 October 2025)","url":"https://www.conservatives.wales/news/welsh-conservatives-appoint-surgeon-ceo-and-top-headteacher-health-economy-and-education"}},{"label":"Business","text":"He founded and managed biotechnology companies including Bioenvision Inc and NuCana Biomed.","source":{"title":"Welsh Conservatives: Welsh Conservatives appoint surgeon, CEO and top headteacher for health, economy and education (3 October 2025)","url":"https://www.conservatives.wales/news/welsh-conservatives-appoint-surgeon-ceo-and-top-headteacher-health-economy-and-education"}},{"label":"Business","text":"In 2009 he founded Medannex, a biopharmaceutical company developing treatments for cancer and autoimmune diseases.","source":{"title":"The Independent (via Yahoo News): The Conservative Party's biggest donors, from Mohamed Mansour to Frank Hester (29 March 2024)","url":"https://ca.news.yahoo.com/conservative-party-biggest-donors-frank-161643555.html"}},{"label":"Business","text":"Companies House lists him as a director of Medannex Limited since 2010, Oncobiopharm Limited since 2006 and Edixomed Limited since 2011, and as a former director of NuCana plc (1997 to 2020) and Mina Therapeutics Limited (2014 to 2023).","source":{"title":"Companies House: Christopher Barry WOOD, appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/HQrFtYOeJXRB6X3P6xT2W0e-P_M/appointments"}},{"label":"Ownership and control","text":"Companies House recorded him as a person with significant control of Medannex Limited, owning more than 25 per cent but not more than 50 per cent of its shares, from April 2016 until August 2020.","source":{"title":"Companies House: MEDANNEX LIMITED (SC363190), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/SC363190/persons-with-significant-control"}},{"label":"Public roles","text":"In October 2025 the Welsh Conservatives appointed him as their Healthcare Improvement Advisor, advising the party on health policy ahead of the 2026 Senedd elections.","source":{"title":"Welsh Conservatives: Welsh Conservatives appoint surgeon, CEO and top headteacher for health, economy and education (3 October 2025)","url":"https://www.conservatives.wales/news/welsh-conservatives-appoint-surgeon-ceo-and-top-headteacher-health-economy-and-education"}}]$df$::jsonb),
  ('christopher-john-rea', 'Chris Rea (Christopher John Rea)', 'individual', 8, $df$[{"label":"Who they are","text":"Chris Rea, from County Down in Northern Ireland, is the founder and managing director of AESSEAL, a manufacturer based in Rotherham.","source":{"title":"Rothbiz: New Year's Honours for Rotherham based business people (6 January 2020)","url":"https://www.rothbiz.co.uk/2020/01/news-7200-new-years-honours-for.html"}},{"label":"Business","text":"He grew a small mechanical seals design and manufacturing business, which had five staff in 1979, into the global group AES Engineering Ltd.","source":{"title":"Invest Rotherham: AESSEAL MD Chris Rea awarded Honorary Fellowship by IMechE (19 November 2020)","url":"https://www.investrotherham.com/business/aesseal-md-awarded-honorary-fellowship-by-imeche/"}},{"label":"Ownership and control","text":"Companies House records Mr Christopher John Rea as holding more than 50 per cent but less than 75 per cent of the shares and voting rights in A.E.S. Engineering Limited, with 3i Group Plc and 3i Investments Plc each listed as holding more than 25 per cent but not more than 50 per cent.","source":{"title":"Companies House: A.E.S. Engineering Limited (00392743), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/00392743/persons-with-significant-control"}},{"label":"Ownership and control","text":"A.E.S. Engineering Limited owns 75 per cent or more of the shares and voting rights in AESSEAL PLC (02101607).","source":{"title":"Companies House: AESSEAL PLC (02101607), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/02101607/persons-with-significant-control"}},{"label":"Ownership and control","text":"Christopher John Rea has been a director of AESSEAL PLC since before July 1991.","source":{"title":"Companies House: AESSEAL PLC (02101607), officers","url":"https://find-and-update.company-information.service.gov.uk/company/02101607/officers"}},{"label":"Size","text":"In November 2023 the group took on its 2,000th employee, operated from more than 231 locations in 104 countries and had a turnover of nearly £200 million.","source":{"title":"Rothbiz: AES takes on 2,000th employee (2 November 2023)","url":"https://www.rothbiz.co.uk/2023/11/news-8324-aes-takes-on-2000th-employee.html"}},{"label":"Public roles","text":"He is a Deputy Lieutenant for South Yorkshire.","source":{"title":"Invest Rotherham: AESSEAL MD Chris Rea awarded Honorary Fellowship by IMechE (19 November 2020)","url":"https://www.investrotherham.com/business/aesseal-md-awarded-honorary-fellowship-by-imeche/"}},{"label":"Honours","text":"He was appointed CBE in the 2020 New Year Honours for services to business, innovation and exports.","source":{"title":"IMechE: Chris Rea awarded IMechE Honorary Fellowship","url":"https://www.imeche.org/news/news-article/chris-rea-awarded-imeche-honorary-fellowship"}}]$df$::jsonb),
  ('david-grainger', 'Dr David Grainger', 'individual', 4, $df$[{"label":"Who they are","text":"Press reports of the first quarter 2026 donation figures describe David Grainger, who gave about £1,150,000 to Reform UK over that period, as a biotechnology executive and venture capitalist.","source":{"title":"Nation.Cymru: Reform top recipient of political donations in first quarter of year with £9m (4 June 2026)","url":"https://nation.cymru/news/reform-top-recipient-of-political-donations-in-first-quarter-of-year-with-9m/"}},{"label":"Business","text":"David Grainger studied biochemistry and took a PhD at Cambridge, founded FingerPrint Diagnostics in 2001 and Funxional Therapeutics in 2005, joined the life sciences team at Index Ventures in 2012, co founded Medicxi in 2016 with former Index Ventures partners, and is chief executive of Methuselah Health.","source":{"title":"Wikipedia: David Grainger","url":"https://en.wikipedia.org/wiki/David_Grainger"}},{"label":"Business","text":"Companies House lists Dr David John Grainger as a director of Methuselah Health UK Limited and of The Cambridge Partnership Limited since 2014, and as a designated member of Total Medical Ventures I LLP since 2009.","source":{"title":"Companies House: Dr David John GRAINGER, personal appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/wg1JKqKzFVsuxA-LA5b2kC5IPs8/appointments"}},{"label":"Business","text":"He is also a director of a group of companies registered since 2019, including Perfect Balance Bio Limited, S Xpress Bio Limited, Imhotex Limited and Barkway House Estates Limited.","source":{"title":"Companies House: Dr David John GRAINGER, personal appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/nmMfERy2JEFaKfzUBQjJ8hsFcL0/appointments"}}]$df$::jsonb),
  ('jeremy-elliott-san', 'Jez San (Jeremy Elliott San)', 'individual', 6, $df$[{"label":"Who they are","text":"Jeremy Elliott \"Jez\" San, born in 1966, is a British video game entrepreneur who founded Argonaut Software as a teenager in the 1980s.","source":{"title":"Wikipedia: Jez San","url":"https://en.wikipedia.org/wiki/Jez_San"}},{"label":"Who they are","text":"Press reports of the 2025 party funding figures describe the donor of the £1 million gifts to the Conservatives in February 2025 and in the second quarter of 2025 as video game entrepreneur Jez San.","source":{"title":"Nation.Cymru: Tory donations fall despite video game entrepreneur's £1m gift (4 September 2025)","url":"https://nation.cymru/news/tory-donations-fall-despite-video-game-entrepreneurs-1m-gift"}},{"label":"Business","text":"After Argonaut he founded the online poker company PKR, which he served as president, co founded Origin8 in 2008, and in 2017 started FunFair, a blockchain based video game company.","source":{"title":"Wikipedia: Jez San","url":"https://en.wikipedia.org/wiki/Jez_San"}},{"label":"Business","text":"Companies House lists Jeremy Elliott San as a director of Ninja Theory Limited from 2004 to 2018, PKR Technologies Limited from 2004 to 2016, and ARC International Limited, and as a director of Origin 8 Technologies Limited from 2008 until March 2025 and of DMS Holdings Limited from 1997 until April 2025.","source":{"title":"Companies House: Jeremy Elliott SAN, personal appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/JPzNBC7PtwaCHSy9Wjl14h8eHEw/appointments"}},{"label":"Business","text":"He was a director of FunFair Technologies Ltd from August 2018 to March 2024.","source":{"title":"Companies House: Jeremy Elliott SAN, personal appointments (FunFair Technologies)","url":"https://find-and-update.company-information.service.gov.uk/officers/QnnGio6gTHWFxrLk0OXE2i2eMY8/appointments"}},{"label":"Honours","text":"He was appointed OBE in 2002, described as the first OBE awarded explicitly for services to the video game industry.","source":{"title":"Wikipedia: Jez San","url":"https://en.wikipedia.org/wiki/Jez_San"}}]$df$::jsonb),
  ('kamal-pankhania', 'Kamal Pankhania', 'individual', 7, $df$[{"label":"Who they are","text":"Kamal Pankhania is the Chief Executive of the Westcombe Group, a property development company.","source":{"title":"British Asian Trust: Kamal Pankhania","url":"https://www.britishasiantrust.org/support-us/advisory-councils/kamal-pankhania/"}},{"label":"Business","text":"Westcombe converts Grade I and Grade II listed buildings into hotels, commercial space and homes; its hotel arm, the Acre Hotels Collection, has partnerships with Hilton, Accor and IHG.","source":{"title":"British Asian Trust: Kamal Pankhania","url":"https://www.britishasiantrust.org/support-us/advisory-councils/kamal-pankhania/"}},{"label":"Business","text":"Eastern Eye reported that Westcombe Developments Limited, a property company linked to Kamal, Sunil and Vraj Pankhania, gave £100,000 to the Conservatives in August (article dated December 2025).","source":{"title":"Eastern Eye: Kamal Pankhania, Koolesh Shah, Malik Karim among Asian party donors (11 December 2025)","url":"https://www.easterneye.biz/kamal-pankhania-koolesh-shah-malik-karim-among-asian-party-donors"}},{"label":"Ownership and control","text":"He owns 75 per cent or more of the shares in Westcombe Group Limited (company 13643624), registered since March 2023.","source":{"title":"Companies House: WESTCOMBE GROUP LIMITED (13643624), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/13643624/persons-with-significant-control"}},{"label":"Ownership and control","text":"He holds more than 25 per cent but not more than 50 per cent of The Westcombe Group (U.K.) Limited, alongside Sunil Pankhania and Vraj Pankhania.","source":{"title":"Companies House: THE WESTCOMBE GROUP (U.K.) LIMITED (14186225), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/14186225/persons-with-significant-control"}},{"label":"Ownership and control","text":"Companies House lists 36 appointments for Kamal Pankhania (born September 1977), including Westcombe Developments Limited, Westcombe Homes Limited and Acre Hotels Limited.","source":{"title":"Companies House: Kamal PANKHANIA, appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/4_uQMVZ4s-UuVxLIfdMS3QYAvD0/appointments"}},{"label":"Sector interests","text":"The registered nature of business of The Westcombe Group (U.K.) Limited is development of building projects.","source":{"title":"Companies House: THE WESTCOMBE GROUP (U.K.) LIMITED (14186225), overview","url":"https://find-and-update.company-information.service.gov.uk/company/14186225"}}]$df$::jsonb),
  ('mark-petterson', 'Mark Petterson (Lord Petterson)', 'individual', 8, $df$[{"label":"Who they are","text":"Mark Petterson is an offshore wind developer and a Liberal Democrat member of over 25 years who was nominated for a life peerage by the Liberal Democrat leader in July 2026.","source":{"title":"Liberal Democrats: Five new Lib Dem peers (2026)","url":"https://www.libdems.org.uk/news/article/2026-peers"}},{"label":"Business","text":"He is a director of Warwick Energy, a company he founded with others in 2000; its projects include Thanet, the largest offshore wind farm in the world when it came onstream in 2010.","source":{"title":"Liberal Democrats: Five new Lib Dem peers (2026)","url":"https://www.libdems.org.uk/news/article/2026-peers"}},{"label":"Business","text":"Companies House lists Mark Edward Petterson (born June 1960) as a director of Warwick Energy Limited since November 2000, and formerly of Dudgeon Offshore Wind Limited (2002 to 2012), Total Gas Marketing Limited (1994 to 1996) and Corona Energy Limited (1997 to 1998).","source":{"title":"Companies House: Mark Edward PETTERSON, appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/qi9qH-NM54aUsnJ6pZ8Usb5B5hE/appointments"}},{"label":"Ownership and control","text":"He holds more than 25 per cent but not more than 50 per cent of the shares in Warwick Energy Holdings Limited, alongside John Leslie Sulley and Dr Robert Evan Jones; the holding company owns 75 per cent or more of Warwick Energy Limited.","source":{"title":"Companies House: WARWICK ENERGY HOLDINGS LIMITED (05065965), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/05065965/persons-with-significant-control"}},{"label":"Public roles","text":"His nomination for a life peerage was announced on 16 July 2026, describing him as Director of Warwick Energy Limited and a longstanding adviser to the Liberal Democrats.","source":{"title":"GOV.UK: Political peerages July 2026 (16 July 2026)","url":"https://www.gov.uk/government/news/political-peerages-july-2026"}},{"label":"Public roles","text":"Parliament lists him as The Lord Petterson, a member of the House of Lords who has not yet been introduced.","source":{"title":"UK Parliament: Lord Petterson","url":"https://members.parliament.uk/member/5473"}},{"label":"Public roles","text":"Within the Liberal Democrats he has given the party energy policy advice and served on its Business and Economic Council and its Fundraising Committee, according to his own manifesto for English Council elections.","source":{"title":"South Central Liberal Democrats: Mark Petterson manifesto","url":"https://www.southcentrallibdems.org.uk/fileadmin/groups/186/Mark_Petterson_manifesto-2.pdf"}},{"label":"Sector interests","text":"Warwick Energy Limited's registered nature of business is extraction of natural gas, production of electricity and other specialised construction activities.","source":{"title":"Companies House: WARWICK ENERGY LIMITED (04095285), overview","url":"https://find-and-update.company-information.service.gov.uk/company/04095285"}}]$df$::jsonb),
  ('mou-operations', 'MOU Operations Ltd', 'company', 8, $df$[{"label":"Who they are","text":"MOU Operations Ltd is a private company limited by guarantee without share capital, incorporated on 2 April 2025, whose nature of business is listed as activities of political organisations.","source":{"title":"Companies House: MOU OPERATIONS LTD overview (16359847)","url":"https://find-and-update.company-information.service.gov.uk/company/16359847"}},{"label":"Business","text":"Its accounts state that it was set up as a vehicle to raise funds for Your Party, a new political party; it raised £934,331, transferred £852,303 to Your Party and spent the remaining £82,028 on the costs of setting up the party, and has now ceased to operate.","source":{"title":"Companies House: MOU OPERATIONS LTD directors' report and unaudited financial statements, 2 April 2025 to 30 September 2026 (filed 5 October 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/16359847/filing-history/MzU0OTI2Mzc0NGFkaXF6a2N4/document?format=xhtml&download=1"}},{"label":"Business","text":"In September 2025 the Press Association described it as the organisation handling Your Party's donations.","source":{"title":"Express & Star (PA): Corbyn defends ally as Your Party feud continues (20 September 2025)","url":"https://www.expressandstar.com/uk-news/2025/09/20/corbyn-defends-ally-as-your-party-feud-continues"}},{"label":"Ownership and control","text":"The company states that it has no registrable person with significant control.","source":{"title":"Companies House: MOU OPERATIONS LTD persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/16359847/persons-with-significant-control"}},{"label":"Ownership and control","text":"Its first directors, from 2 April 2025, were Jamie Driscoll, Andrew Feinstein and Dr Bethan Winter, who all resigned in late October 2025; Zarah Sultana has been its sole director since 28 October 2025.","source":{"title":"Companies House: MOU OPERATIONS LTD officers","url":"https://find-and-update.company-information.service.gov.uk/company/16359847/officers"}},{"label":"Ownership and control","text":"A resolution filed in November 2025 records a transfer of £200,000 to Your Party UK Limited dated 12 November 2025. In October 2026 the company applied to be struck off the register, and a first Gazette notice for voluntary strike off followed on 13 October 2026.","source":{"title":"Companies House: MOU OPERATIONS LTD filing history","url":"https://find-and-update.company-information.service.gov.uk/company/16359847/filing-history"}},{"label":"Size","text":"Its accounts for 2 April 2025 to 30 September 2026 report no employees and operating income and administrative expenses of £82,028 each.","source":{"title":"Companies House: MOU OPERATIONS LTD directors' report and unaudited financial statements, 2 April 2025 to 30 September 2026 (filed 5 October 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/16359847/filing-history/MzU0OTI2Mzc0NGFkaXF6a2N4/document?format=xhtml&download=1"}},{"label":"Public roles","text":"Its director Zarah Sultana is the MP for Coventry South, first elected on 12 December 2019.","source":{"title":"UK Parliament: Zarah Sultana MP","url":"https://members.parliament.uk/member/4786/career"}}]$df$::jsonb),
  ('nick-candy', 'Nick Candy', 'individual', 5, $df$[{"label":"Who they are","text":"Nick Candy is a billionaire property developer and former Conservative donor who gave more than £270,000 to the Conservative Party under Boris Johnson's leadership.","source":{"title":"BBC News: Farage recruits tycoon Nick Candy as Reform UK treasurer (10 December 2024)","url":"https://www.bbc.co.uk/news/articles/czr3n6g4lyjo"}},{"label":"Business","text":"He made his money buying and renovating properties with his brother Christian; the pair bought their first London property in 1995.","source":{"title":"BBC News: Farage recruits tycoon Nick Candy as Reform UK treasurer (10 December 2024)","url":"https://www.bbc.co.uk/news/articles/czr3n6g4lyjo"}},{"label":"Business","text":"Companies House lists Nicholas Anthony Christopher Candy (born January 1973) as a director of Candy Middle East Limited since March 2024 and of Blippar Limited since January 2019, among 45 appointments.","source":{"title":"Companies House: Nicholas Anthony Christopher CANDY, appointments","url":"https://find-and-update.company-information.service.gov.uk/officers/XAqgpvqYJsSdCxibG6OlxBeS1jE/appointments"}},{"label":"Ownership and control","text":"He is the person with significant control of Candy Capital Limited (company 09328316, formerly The Nicholas Candy Group of Companies Limited), holding 75 per cent or more of its shares and voting rights.","source":{"title":"Companies House: CANDY CAPITAL LIMITED (09328316), persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/09328316/persons-with-significant-control"}},{"label":"Public roles","text":"Reform UK appointed him as its party treasurer in December 2024, with the job of raising money to fight the next general election.","source":{"title":"BBC News: Farage recruits tycoon Nick Candy as Reform UK treasurer (10 December 2024)","url":"https://www.bbc.co.uk/news/articles/czr3n6g4lyjo"}}]$df$::jsonb),
  ('renewable-energy-partnerships', 'Renewable Energy Partnerships Ltd', 'company', 7, $df$[{"label":"Who they are","text":"Renewable Energy Partnerships Limited is a private limited company incorporated on 25 November 2002, with its registered office at Stoney Stratton, Shepton Mallet, Somerset.","source":{"title":"Companies House: RENEWABLE ENERGY PARTNERSHIPS LIMITED overview (04599328)","url":"https://find-and-update.company-information.service.gov.uk/company/04599328"}},{"label":"Business","text":"Its accounts describe its principal activity as early stage windfarm development and consulting and advisory services to businesses in the windfarm renewable energy sector, and state that it is no longer trading but continues to receive residual income from its previous windfarm development activity.","source":{"title":"Companies House: RENEWABLE ENERGY PARTNERSHIPS LIMITED unaudited financial statements for the year ended 31 December 2024 (filed 30 September 2025)","url":"https://find-and-update.company-information.service.gov.uk/company/04599328/filing-history/MzQ4MzE5OTk4MmFkaXF6a2N4/document?format=xhtml&download=1"}},{"label":"Ownership and control","text":"Its persons with significant control, since 25 January 2019, are Richard Thomas Hadwin, with more than 50 per cent but less than 75 per cent of shares and votes, and Elizabeth Anne Hadwin, with more than 25 per cent but not more than 50 per cent.","source":{"title":"Companies House: RENEWABLE ENERGY PARTNERSHIPS LIMITED persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/04599328/persons-with-significant-control"}},{"label":"Ownership and control","text":"Richard Thomas Hadwin has been a director since the company was incorporated in 2002 and its company secretary since 1 February 2004.","source":{"title":"Companies House: RENEWABLE ENERGY PARTNERSHIPS LIMITED officers","url":"https://find-and-update.company-information.service.gov.uk/company/04599328/officers"}},{"label":"Size","text":"Its accounts for the year to 31 December 2024 show net assets of £1,715,917, including cash of £1,687,199, and an average of one person employed, including the director.","source":{"title":"Companies House: RENEWABLE ENERGY PARTNERSHIPS LIMITED unaudited financial statements for the year ended 31 December 2024 (filed 30 September 2025)","url":"https://find-and-update.company-information.service.gov.uk/company/04599328/filing-history/MzQ4MzE5OTk4MmFkaXF6a2N4/document?format=xhtml&download=1"}},{"label":"Public roles","text":"The Electoral Commission register lists Richard Hadwin as leader, nominating officer and treasurer of the Open Party, the company's only recipient, and Elizabeth Hadwin as an additional officer.","source":{"title":"Electoral Commission: registration PP17475, Open Party","url":"https://search.electoralcommission.org.uk/English/Registrations/PP17475"}},{"label":"Public roles","text":"Nation.Cymru reported in December 2025 that the Open Party, led by Richard Hadwin, had launched in Wales and was piloting its approach in the Casnewydd Islwyn constituency at the May 2026 Senedd election.","source":{"title":"Nation.Cymru: New political party launches in Wales and invites public to stand as candidates (2 December 2025)","url":"https://nation.cymru/news/new-political-party-launches-in-wales-and-invites-public-to-stand-as-candidates"}}]$df$::jsonb),
  ('scottish-unionist-association-trust', 'Scottish Unionist Association Trust', 'trust', 7, $df$[{"label":"Who they are","text":"The Electoral Commission records the Scottish Unionist Association Trust as an unincorporated association with an address at 570 Mosspark Boulevard, Glasgow.","source":{"title":"Electoral Commission: donations search, Scottish Unionist Association Trust","url":"https://search.electoralcommission.org.uk/English/Search/Donations?query=Scottish%20Unionist%20Association%20Trust"}},{"label":"Who they are","text":"Its trustees have said it was formed in 1968 from the assets, primarily property sales, of the then Scottish Unionist Association.","source":{"title":"The Ferret: Tory dark money trust address and trustees (4 July 2018)","url":"https://theferret.scot/tory-dark-money-trust-address-trustees/"}},{"label":"Business","text":"Its trustees have said it invests its assets and makes the proceeds available to further the aims of the Scottish Conservative and Unionist Party.","source":{"title":"The Ferret: Tory dark money trust address and trustees (4 July 2018)","url":"https://theferret.scot/tory-dark-money-trust-address-trustees/"}},{"label":"Ownership and control","text":"In 2018 its chairman was Robert Miller-Bakewell, and its trustees were volunteers and Scottish Conservative party members. It took over the assets of the Glasgow Unionist Association Trust when the two merged in 2013.","source":{"title":"The Ferret: Tory dark money trust reveals £2.35m assets (19 July 2018)","url":"https://theferret.scot/tory-dark-money-trust-2-35m"}},{"label":"Size","text":"The trust said its net assets at the end of 2017 were worth £2.35m, predominantly invested in UK listed equity investments.","source":{"title":"The Ferret: Tory dark money trust reveals £2.35m assets (19 July 2018)","url":"https://theferret.scot/tory-dark-money-trust-2-35m"}},{"label":"Official findings","text":"In 2019 the Electoral Commission fined the trust £1,800 in three fines: for not notifying contributions of over £25,000 it made to the Conservative and Unionist Party in 2010, 2015, 2016 and 2017 within the required time, and for reporting late two donations it received, £50,000 in February 2014 and £157,350.07 in March 2017. It paid the fines in August 2019.","source":{"title":"Holyrood: Scottish Unionist Association Trust fined for failing to properly declare donations (4 October 2019)","url":"https://www.holyrood.com/news/view,scottish-unionist-association-trust-fined-for-failing-to-properly-declare-donations_10821.htm"}},{"label":"Official findings","text":"In June 2020 the Electoral Commission fined the trust a further £300 for reporting a donation late.","source":{"title":"The Ferret: Election watchdog issues second fine to Tory trust (16 June 2020)","url":"https://www.theferret.scot/election-watchdog-second-fine-tory-dark-money-trust.md"}}]$df$::jsonb),
  ('tisun-investments', 'TISUN Investments Limited', 'company', 8, $df$[{"label":"Who they are","text":"TISUN Investments Ltd is a private limited company incorporated on 5 September 2006, with its registered office at 24 Berkeley Square, London.","source":{"title":"Companies House: TISUN INVESTMENTS LTD overview (05925324)","url":"https://find-and-update.company-information.service.gov.uk/company/05925324"}},{"label":"Business","text":"Companies House lists its nature of business as security and commodity contracts dealing activities. Its accounts for 2024 record investments and an investment property among its assets.","source":{"title":"Companies House: TISUN INVESTMENTS LTD overview (05925324)","url":"https://find-and-update.company-information.service.gov.uk/company/05925324"}},{"label":"Ownership and control","text":"Its person with significant control is Tisun Holdco Limited, which has held 75 per cent or more of the shares and voting rights since 20 November 2020. Before that the company was controlled by Sunley Family Limited and then, briefly in 2020, Sunley Family Holding Limited.","source":{"title":"Companies House: TISUN INVESTMENTS LTD persons with significant control","url":"https://find-and-update.company-information.service.gov.uk/company/05925324/persons-with-significant-control"}},{"label":"Ownership and control","text":"Richard Tice is the person with significant control of Tisun Holdco Limited, holding 75 per cent or more of its shares and voting rights since 17 March 2020.","source":{"title":"Companies House: TISUN HOLDCO LIMITED persons with significant control (12521429)","url":"https://find-and-update.company-information.service.gov.uk/company/12521429/persons-with-significant-control"}},{"label":"Ownership and control","text":"Richard James Sunley Tice has been its director since 5 September 2006, and Sunley Securities Limited has been its company secretary since the same date.","source":{"title":"Companies House: TISUN INVESTMENTS LTD officers","url":"https://find-and-update.company-information.service.gov.uk/company/05925324/officers"}},{"label":"Size","text":"Its unaudited accounts for the year to 31 December 2024 show net assets of £2,252,984, a loss for the year of £256,943 and an average of one employee, including the director.","source":{"title":"Companies House: TISUN INVESTMENTS LTD unaudited financial statements for the year ended 31 December 2024 (filed 5 January 2026)","url":"https://find-and-update.company-information.service.gov.uk/company/05925324/filing-history/MzQ5NzEyNDI0NGFkaXF6a2N4/document?format=pdf&download=0"}},{"label":"Public roles","text":"Its owner Richard Tice has been the Reform UK MP for Boston and Skegness since 4 July 2024.","source":{"title":"UK Parliament: Richard Tice MP","url":"https://members.parliament.uk/member/5161/career"}},{"label":"Public roles","text":"Richard Tice was chairman of the Brexit Party, later renamed Reform UK, from April 2019 to March 2021, its leader from March 2021 to June 2024, and has been its deputy leader since 11 July 2024.","source":{"title":"Wikipedia: Richard Tice","url":"https://en.wikipedia.org/wiki/Richard_Tice"}}]$df$::jsonb);

DO $$ BEGIN
  IF (SELECT count(*) FROM public.donor_profiles p JOIN dp_file f USING (key) WHERE md5(p.facts::text) = md5(f.facts::text)) <> 13 THEN
    RAISE EXCEPTION 'a batch 2 profile no longer holds the 2026-10-31l facts (changed since)';
  END IF;
END $$;

DELETE FROM public.donor_profile_slugs WHERE slug = 'jcb-sales-ltd' AND key = 'jcb';
DELETE FROM public.donor_profiles p USING dp_file f WHERE p.key = f.key AND md5(p.facts::text) = md5(f.facts::text);

DO $$
DECLARE profiles integer; slug_rows integer; fact_total integer; old_changed integer;
BEGIN
  SELECT count(*) INTO profiles FROM public.donor_profiles;
  SELECT count(*) INTO slug_rows FROM public.donor_profile_slugs;
  SELECT sum(jsonb_array_length(facts)) INTO fact_total FROM public.donor_profiles;
  SELECT count(*) INTO old_changed FROM prof_before b LEFT JOIN public.donor_profiles p USING (key) WHERE p.key IS NULL OR md5(to_jsonb(p)::text) <> b.h;
  RAISE NOTICE 'UNDO: profiles %, slugs %, facts %, earlier profiles changed %', profiles, slug_rows, fact_total, old_changed;
  IF profiles <> 25 THEN RAISE EXCEPTION 'expected 25 profiles after the undo, got %', profiles; END IF;
  IF slug_rows <> 41 THEN RAISE EXCEPTION 'expected 41 slugs after the undo, got %', slug_rows; END IF;
  IF fact_total <> 172 THEN RAISE EXCEPTION 'expected 172 facts after the undo, got %', fact_total; END IF;
  IF old_changed <> 0 THEN RAISE EXCEPTION '% earlier profiles changed', old_changed; END IF;
END $$;

COMMIT;
